const HTML = "<!doctype html>\n<html lang=\"fr\"><head><meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Qui veut gagner des millions ?</title>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js\"></script>\n<link href=\"https://fonts.googleapis.com/css2?family=Cinzel:wght@600;800&family=Raleway:wght@500;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{color-scheme:dark;--gold:#e9c46a;--gold2:#a8791f;--navy:#071457;--navy2:#0d2a8f;--orange:#f08a00;--green:#18a64a;--red:#d62839;--txt:#f4f6ff;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}\n*,*::before,*::after{box-sizing:inherit}\nhtml{scroll-padding-top:env(safe-area-inset-top,0px)}\nhtml,body{margin:0;min-height:100%;background:#030828;color:var(--txt);font-family:Raleway,system-ui,sans-serif}\nbody{background:radial-gradient(ellipse at 50% 25%,#1a44b8 0,#0a1a5c 48%,#030828 100%) fixed;overflow-x:hidden}\nbody::before{content:\"\";position:fixed;inset:-50%;background:repeating-conic-gradient(from 0deg at 50% 40%,rgba(255,255,255,.05) 0 6deg,transparent 6deg 18deg);animation:spin 80s linear infinite;pointer-events:none}\n@keyframes spin{to{transform:rotate(360deg)}}\nh1,.cin{font-family:Cinzel,Georgia,serif}\n[hidden]{display:none!important}\n.hex{--c:polygon(3% 0,97% 0,100% 50%,97% 100%,3% 100%,0 50%);clip-path:var(--c);background:linear-gradient(var(--gold),var(--gold2),var(--gold));padding:2px}\n.hex>.in{clip-path:var(--c);background:linear-gradient(#0f2fa0,#06104a);display:flex;align-items:center;min-height:100%;padding:14px 5%}\n/* intro */\n#intro,#end{position:relative;min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:22px;text-align:center;padding:24px}\n#end{position:fixed;inset:0;z-index:5;background:rgba(3,8,40,.92);animation:fade .6s}\n@keyframes fade{from{opacity:0}}\n.ring{width:min(78vw,340px);aspect-ratio:1;border-radius:50%;display:grid;place-items:center;background:radial-gradient(circle,#1b3fb5,#050d44);border:4px solid var(--gold);box-shadow:0 0 0 8px rgba(233,196,106,.18),0 0 60px 10px rgba(60,110,255,.55);animation:glow 3s ease-in-out infinite}\n@keyframes glow{50%{box-shadow:0 0 0 14px rgba(233,196,106,.1),0 0 90px 24px rgba(90,140,255,.7)}}\n.ring h1{margin:0;font-size:clamp(24px,6vw,36px);line-height:1.15;padding:0 14%;text-shadow:0 2px 12px #000;font-weight:800}\n.btn{font:700 17px Raleway,sans-serif;color:#1a1000;background:linear-gradient(#ffe39a,var(--gold),var(--gold2));border:0;border-radius:40px;padding:13px 34px;cursor:pointer;transition:transform .15s,filter .15s}\n.btn:hover{transform:scale(1.05);filter:brightness(1.1)}\n.btn.alt{color:var(--txt);background:rgba(255,255,255,.12);border:1px solid var(--gold)}\n:focus-visible{outline:3px solid #fff;outline-offset:3px}\n/* game */\n#game{position:relative;display:grid;grid-template-columns:1fr 250px;gap:20px;max-width:1100px;margin:0 auto;padding:16px;min-height:100vh}\n.stage{display:flex;flex-direction:column;justify-content:flex-end;gap:14px}\n.top{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}\n.lifes{display:flex;gap:10px}\n.life{width:74px;height:44px;border-radius:50%;border:2px solid var(--gold);background:radial-gradient(#2250d0,#071457);color:var(--txt);font:800 14px Cinzel,serif;cursor:pointer;position:relative;transition:transform .2s}\n.life:not(:disabled):hover{transform:scale(1.1)}\n.life:not(:disabled){animation:ping 2.4s infinite}\n@keyframes ping{0%{box-shadow:0 0 0 0 rgba(233,196,106,.7)}70%,100%{box-shadow:0 0 0 12px transparent}}\n.life:disabled{opacity:.45;cursor:not-allowed;animation:none}\n.life.used::after{content:\"✕\";position:absolute;inset:0;display:grid;place-items:center;font-size:40px;color:var(--red);text-shadow:0 0 4px #000}\n#info{font-weight:700;color:var(--gold);text-align:center;letter-spacing:.02em}\n#qbox{min-height:96px;font-size:clamp(17px,2.6vw,23px);font-weight:700;line-height:1.35;text-align:center;justify-content:center}\n#qbox .in{justify-content:center}\n#answers{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.ans{--c:polygon(5% 0,95% 0,100% 50%,95% 100%,5% 100%,0 50%);border:0;cursor:pointer;color:var(--txt);font:700 clamp(15px,2vw,19px) Raleway,sans-serif;text-align:left;padding:2px;opacity:0;transform:translateX(-24px);transition:filter .15s}\n.ans.show{animation:slide .45s forwards;animation-delay:calc(var(--i)*.35s)}\n@keyframes slide{to{opacity:1;transform:none}}\n.ans .in{padding:13px 8%;gap:10px}\n.ans b{color:var(--orange);font-family:Cinzel,serif;font-size:1.1em}\n.ans:not(:disabled):hover{filter:brightness(1.25)}\n.ans.gone{visibility:hidden}\n.ans.sel{background:var(--orange)}.ans.sel .in{background:linear-gradient(#ffb23a,#e07a00);color:#1a1000}.ans.sel b{color:#1a1000}\n.ans.sel.pend{animation:none;}\n.ans.sel.pend .in{animation:bl .5s steps(2) infinite}\n@keyframes bl{50%{filter:brightness(.7)}}\n.ans.ok{background:#8fffae}.ans.ok .in{background:linear-gradient(#2fd067,var(--green));animation:flash .35s 6}.ans.ok b{color:#fff}\n.ans.ko{background:#ff9aa4}.ans.ko .in{background:linear-gradient(#f04658,var(--red))}.ans.ko b{color:#fff}\n@keyframes flash{50%{filter:brightness(1.9)}}\n#panel{min-height:64px;display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:center;text-align:center}\n#panel p{margin:0;font-weight:700}\n.bars{display:flex;gap:16px;align-items:flex-end;height:110px;padding:6px 14px;background:rgba(0,0,0,.35);border:1px solid var(--gold);border-radius:10px}\n.bar{width:38px;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;height:100%;font-size:12px;font-weight:700}\n.bar i{display:block;width:100%;background:linear-gradient(var(--orange),#a35500);border-radius:4px 4px 0 0;height:0;transition:height 1.2s}\n/* ladder */\n#ladder{list-style:none;margin:0;padding:10px;display:flex;flex-direction:column-reverse;justify-content:flex-end;gap:3px;align-self:end;background:rgba(0,0,0,.35);border:2px solid var(--gold2);border-radius:14px}\n#ladder li{display:flex;justify-content:space-between;padding:5px 12px;border-radius:6px;font:800 15px Cinzel,serif;color:var(--orange);transition:all .4s}\n#ladder li.safe{color:#fff}\n#ladder li.done{opacity:.5}\n#ladder li.cur{background:linear-gradient(#ffb23a,#e07a00);color:#1a1000;opacity:1;transform:scale(1.06);animation:pulse 1.2s infinite}\n@keyframes pulse{50%{box-shadow:0 0 18px 2px rgba(255,170,40,.8)}}\n#gain{font:800 clamp(34px,9vw,60px) Cinzel,serif;color:var(--gold);text-shadow:0 0 24px rgba(233,196,106,.7);animation:pop .8s cubic-bezier(.2,1.6,.4,1)}\n@keyframes pop{from{transform:scale(.2);opacity:0}}\n.conf{position:fixed;top:-20px;width:10px;height:16px;animation:fall linear forwards;z-index:6}\n@keyframes fall{to{transform:translateY(110vh) rotate(720deg)}}\n#mute{position:fixed;right:10px;top:calc(10px + env(safe-area-inset-top,0px));z-index:9;width:40px;height:40px;border-radius:50%;border:1px solid var(--gold);background:rgba(0,0,0,.4);color:#fff;cursor:pointer;font-size:18px}\n#imp{font-size:13px;color:#b8c4ff}\n#timer{display:flex;align-items:center;gap:12px}\n#timer b{width:48px;height:48px;border-radius:50%;display:grid;place-items:center;font:800 22px Cinzel,serif;border:3px solid var(--gold);background:radial-gradient(#2250d0,#071457)}\n#timer i{flex:1;height:8px;border-radius:5px;background:linear-gradient(90deg,var(--orange),var(--gold));transform-origin:left;transition:transform 1s linear}\n#timer.low b{border-color:var(--red);color:#ff8a94;animation:pulse .5s infinite}\n#timer.low i{background:var(--red)}\n#trans{position:fixed;inset:0;z-index:4;background:rgba(3,8,40,.95);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;padding:16px;animation:fade .5s}\n#tmsg{margin:0;font:800 clamp(17px,4vw,22px) Cinzel,serif;color:var(--gold);text-align:center}\n#ladder2{list-style:none;margin:0;padding:10px;display:flex;flex-direction:column-reverse;gap:3px;width:min(92vw,340px);background:rgba(0,0,0,.45);border:2px solid var(--gold2);border-radius:14px}\n#ladder2 li{display:flex;justify-content:space-between;padding:4px 12px;border-radius:6px;font:800 15px Cinzel,serif;color:var(--orange);transition:all .4s}\n#ladder2 li.safe{color:#fff}#ladder2 li.past{opacity:.55}\n#ladder2 li.cur{background:linear-gradient(#ffb23a,#e07a00);color:#1a1000;opacity:1;transform:scale(1.07);animation:pulse 1s infinite}\n.rules{list-style:none;padding:0;margin:0;color:#b8c4ff;font-size:14px;line-height:1.7}\n.row{display:flex;gap:12px;flex-wrap:wrap;justify-content:center}\n#db{position:fixed;inset:0;z-index:5;background:rgba(3,8,40,.97);overflow:auto;padding:20px;display:flex;flex-direction:column;align-items:center;gap:12px}\n#db>*{width:min(100%,640px)}#db h2{margin:0;font-family:Cinzel,serif;color:var(--gold)}\n#db p,#db small{margin:0;color:#b8c4ff;font-size:14px;line-height:1.5}\n#db input,#db select,#db textarea{width:100%;font:500 15px Raleway,sans-serif;color:var(--txt);background:#0a1a5c;border:1px solid var(--gold2);border-radius:8px;padding:9px}\n#db .g{display:grid;grid-template-columns:1fr 1fr;gap:8px}#db .box{border:1px solid var(--gold2);border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:8px}\n#dbmsg{color:var(--gold)!important;font-weight:700}\n@media(max-width:820px){#game{grid-template-columns:1fr;padding:10px}#db .g{grid-template-columns:1fr}#ladder{display:none}#answers{grid-template-columns:1fr}.life{width:62px}}\n@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01s!important;animation-iteration-count:1!important;transition:none!important}.ans{opacity:1;transform:none}}\n#lobby{min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;text-align:center;padding:24px;position:relative}\n#intro input,#lobby input{width:min(100%,300px);font:700 16px Raleway,sans-serif;text-align:center;color:var(--txt);background:#0a1a5c;border:2px solid var(--gold2);border-radius:30px;padding:11px}\n#cd{text-transform:uppercase;letter-spacing:.3em}\n#lpl,#rk{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px;width:min(100%,340px)}\n#lpl li,#rk li{background:rgba(0,0,0,.4);border:1px solid var(--gold2);border-radius:8px;padding:8px 14px;font-weight:700;display:flex;justify-content:space-between;gap:10px;text-align:left}\n#board,#board2{display:flex;flex-wrap:wrap;gap:8px;justify-content:center}\n.pl{background:rgba(0,0,0,.4);border:1px solid var(--gold2);border-radius:20px;padding:5px 12px;font-size:13px;font-weight:700}\n.pl.out{opacity:.55}.pl.me{border-color:var(--orange)}.pl.dn{border-color:#5be38a}\n#herr{color:#ff9aa4;margin:0;min-height:1.2em;font-weight:700}\n#end{overflow:auto}\n</style></head><body>\n<button id=\"mute\" aria-label=\"Couper le son\">🔊</button>\n<section id=\"intro\">\n <div class=\"ring\"><h1>Qui veut gagner des millions ?</h1></div>\n <p style=\"margin:0;color:#b8c4ff\">Jouez ensemble, mêmes questions, en direct</p>\n <input id=\"nm\" maxlength=\"16\" placeholder=\"Votre prénom\" aria-label=\"Votre prénom\" autocomplete=\"nickname\">\n <button class=\"btn\" id=\"mk\">Créer une salle</button>\n <input id=\"cd\" maxlength=\"4\" placeholder=\"CODE\" aria-label=\"Code de la salle\">\n <button class=\"btn alt\" id=\"jn\">Rejoindre</button>\n <p id=\"herr\" role=\"alert\"></p>\n <button class=\"btn alt\" id=\"dbbtn\" style=\"font-size:14px;padding:8px 20px\">Ajouter des questions</button>\n</section>\n<section id=\"lobby\" hidden>\n <h1 class=\"cin\" style=\"margin:0\">Salle <span id=\"lc\"></span></h1>\n <p style=\"margin:0;color:#b8c4ff\">Invitez vos amis avec ce lien :</p>\n <input id=\"lk\" readonly aria-label=\"Lien d’invitation\">\n <div class=\"row\"><button class=\"btn\" id=\"cp\">Copier le lien</button><button class=\"btn alt\" id=\"sh\">Partager</button></div>\n <ul id=\"lpl\"></ul>\n <button class=\"btn\" id=\"go\" hidden>Lancer la partie</button>\n <p id=\"lw\" style=\"margin:0;color:#b8c4ff\"></p>\n</section>\n<main id=\"game\" hidden>\n <div class=\"stage\">\n  <div class=\"top\">\n   <div class=\"lifes\"><button class=\"life\" id=\"fifty\" title=\"Retire deux mauvaises réponses\">50:50</button></div>\n   <button class=\"btn alt\" id=\"walk\">Abandonner et empocher</button>\n  </div>\n  <div id=\"info\"></div><div id=\"timer\"><b>30</b><i></i></div>\n  <div id=\"qbox\" class=\"hex\"><div class=\"in\"><span id=\"qtxt\"></span></div></div>\n  <div id=\"answers\"></div>\n  <div id=\"panel\"></div>\n  <div id=\"board\"></div>\n </div>\n <ol id=\"ladder\" aria-label=\"Échelle des gains\"></ol>\n</main>\n<section id=\"end\" hidden>\n <h1 class=\"cin\" id=\"etitle\" style=\"margin:0\">Classement final</h1><div id=\"gain\"></div>\n <ol id=\"rk\"></ol>\n <div class=\"row\"><button class=\"btn\" id=\"again\" hidden>Rejouer avec le groupe</button><button class=\"btn alt\" id=\"home\">Quitter</button></div>\n <p id=\"ewait\" style=\"margin:0;color:#b8c4ff\"></p>\n</section>\n<section id=\"db\" hidden>\n <h2>Base de questions (partagée)</h2><p id=\"dbst\"></p>\n <div class=\"box\"><b>Importer un fichier Excel</b><p>Colonnes : Question, Réponse A à D, Difficulté, Montant, et une 8e colonne « Bonne réponse » (A, B, C ou D). Sans elle, la réponse surlignée en couleur est utilisée si elle est détectée.</p><input type=\"file\" id=\"xf\" accept=\".xlsx,.xls\" aria-label=\"Fichier Excel\"></div>\n <div class=\"box\"><b>Ajouter une question</b><textarea id=\"fq\" rows=\"2\" placeholder=\"Question\"></textarea>\n <div class=\"g\"><input id=\"fa\" placeholder=\"Réponse A\"><input id=\"fb\" placeholder=\"Réponse B\"><input id=\"fc\" placeholder=\"Réponse C\"><input id=\"fd\" placeholder=\"Réponse D\"><select id=\"fr\" aria-label=\"Bonne réponse\"><option value=\"0\">Bonne réponse : A</option><option value=\"1\">Bonne réponse : B</option><option value=\"2\">Bonne réponse : C</option><option value=\"3\">Bonne réponse : D</option></select><select id=\"fl\" aria-label=\"Difficulté\"></select></div>\n <input id=\"ak\" type=\"password\" placeholder=\"Code admin (si défini par l’hébergeur)\"><button class=\"btn\" id=\"fadd\">Ajouter la question</button></div>\n <p id=\"dbmsg\" role=\"status\"></p>\n <div class=\"row\"><button class=\"btn\" id=\"dbback\">Retour à l’accueil</button></div>\n</section>\n<script>\nconst LV=['Très facile','Facile','Moyen','Plus que moyen','Bien fort','Très fort'];\nconst STEP=[0,0,0,1,1,1,2,2,2,3,3,4,4,4,5];\nconst AM=[1000,2000,3000,5000,10000,20000,30000,40000,50000,75000,100000,200000,300000,500000,1000000];\nconst SAFE=[4,10],$=s=>document.querySelector(s),fmt=n=>n.toLocaleString('fr-FR')+' €';\nconst esc=s=>String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\nconst ss={get:k=>{try{return sessionStorage.getItem(k)}catch(e){return null}},set:(k,v)=>{try{sessionStorage.setItem(k,v)}catch(e){}}};\nconst ls={get:k=>{try{return localStorage.getItem(k)}catch(e){return null}},set:(k,v)=>{try{localStorage.setItem(k,v)}catch(e){}}};\nlet ws,pid=null,code=null,name='',room=null,cur=null,off=0,locked=false,qOpen=false,iAlive=true,lastT=-1,tmr,cdn,muted=false,ac,drone=null,beat=null;\n/* ---- sons ---- */\nfunction tone(f,d=.18,t=0,type='sine'){if(muted)return;try{ac=ac||new(window.AudioContext||window.webkitAudioContext)();const o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.value=f;g.gain.setValueAtTime(.12,ac.currentTime+t);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+t+d);o.connect(g);g.connect(ac.destination);o.start(ac.currentTime+t);o.stop(ac.currentTime+t+d)}catch(e){}}\nconst sfx={sel:()=>tone(440,.2),ok:()=>[523,659,784,1047,1319].forEach((f,i)=>{tone(f,.5,i*.1,'triangle');tone(f/2,.5,i*.1)}),ko:()=>[196,165,131,98].forEach((f,i)=>tone(f,.5,i*.25,'sawtooth')),q:()=>[392,523,659].forEach((f,i)=>tone(f,.4,i*.12,'triangle')),ding:()=>{tone(1175,.5);tone(1568,.5,.12)},win:()=>[523,659,784,1047,784,1047,1319,1568].forEach((f,i)=>tone(f,.45,i*.18,'triangle'))};\nfunction thump(){if(muted||!ac)return;const o=ac.createOscillator(),g=ac.createGain(),t=ac.currentTime;o.frequency.setValueAtTime(90,t);o.frequency.exponentialRampToValueAtTime(40,t+.2);g.gain.setValueAtTime(.35,t);g.gain.exponentialRampToValueAtTime(.001,t+.3);o.connect(g);g.connect(ac.destination);o.start();o.stop(t+.32)}\nfunction setBeat(ms){clearInterval(beat);beat=setInterval(thump,ms)}\nfunction stopAmb(){clearInterval(beat);if(drone){const d=drone;drone=null;try{d.g.gain.setTargetAtTime(0,ac.currentTime,.15);d.o.forEach(o=>o.stop(ac.currentTime+.8))}catch(e){}}}\nfunction startAmb(){stopAmb();if(muted)return;try{ac=ac||new(window.AudioContext||window.webkitAudioContext)();ac.resume();const g=ac.createGain();g.gain.value=0;g.gain.setTargetAtTime(.06,ac.currentTime,.6);g.connect(ac.destination);const o=[55,55.5,82.4,110].map((f,i)=>{const x=ac.createOscillator(),l=ac.createBiquadFilter();x.type=i<2?'sawtooth':'triangle';x.frequency.value=f;l.type='lowpass';l.frequency.value=240;x.connect(l);l.connect(g);x.start();return x});drone={o,g};setBeat(800)}catch(e){}}\n$('#mute').onclick=e=>{muted=!muted;e.target.textContent=muted?'🔇':'🔊';if(muted)stopAmb();else if(qOpen&&iAlive)startAmb()};\n/* ---- réseau ---- */\nconst send=o=>{if(ws&&ws.readyState===1)ws.send(JSON.stringify(o))};\nfunction conn(cb){ws=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host);ws.onopen=cb;ws.onmessage=e=>on(JSON.parse(e.data));\n ws.onclose=()=>{if(code){$('#herr').textContent='Connexion perdue, reconnexion…';setTimeout(()=>conn(()=>send({t:'join',room:code,name,pid})),1500)}else if(!$('#intro').hidden)$('#herr').textContent='Serveur injoignable. Réessayez dans un instant (il peut être en train de se réveiller).'}}\nfunction view(v){['intro','lobby','game','end'].forEach(k=>$('#'+k).hidden=k!==v)}\nfunction on(m){({joined,room:onRoom,q:newQ,hid:onHid,reveal:onReveal,end:onEnd,err:onErr})[m.t]?.(m)}\nfunction joined(m){pid=m.pid;code=m.code;ss.set('pid',pid);ss.set('code',code);$('#herr').textContent=''}\nfunction onErr(m){$('#herr').textContent=m.m;if(m.fatal){code=null;ss.set('code','');view('intro')}}\n/* ---- accueil / salon ---- */\n$('#nm').value=ls.get('nm')||'';\nconst urlRoom=new URLSearchParams(location.search).get('salle');if(urlRoom)$('#cd').value=urlRoom.toUpperCase().slice(0,4);\nconst getName=()=>{name=$('#nm').value.trim();if(!name)$('#herr').textContent='Entrez votre prénom.';else ls.set('nm',name);return name};\n$('#mk').onclick=()=>{if(getName())conn(()=>send({t:'create',name}))};\n$('#jn').onclick=()=>{const c=$('#cd').value.trim().toUpperCase();if(!getName())return;if(c.length!==4){$('#herr').textContent='Entrez le code à 4 lettres.';return}conn(()=>send({t:'join',room:c,name,pid:ss.get('code')===c?ss.get('pid'):null}))};\nif(ss.get('code')&&ss.get('pid')&&ls.get('nm')&&(!urlRoom||urlRoom.toUpperCase()===ss.get('code'))){name=ls.get('nm');conn(()=>send({t:'join',room:ss.get('code'),name,pid:ss.get('pid')}))}\nelse if(urlRoom&&ls.get('nm'))$('#jn').focus();\n$('#cp').onclick=()=>{const l=$('#lk').value;(navigator.clipboard?navigator.clipboard.writeText(l):Promise.reject()).then(()=>$('#cp').textContent='Lien copié ✔',()=>{$('#lk').select()})};\n$('#sh').hidden=!navigator.share;$('#sh').onclick=()=>navigator.share({title:'Qui veut gagner des millions ?',text:'Rejoins ma partie !',url:$('#lk').value}).catch(()=>{});\n$('#go').onclick=()=>{startAmbUnlock();send({t:'start'})};\nfunction startAmbUnlock(){try{ac=ac||new(window.AudioContext||window.webkitAudioContext)();ac.resume()}catch(e){}}\n$('#jn').addEventListener('click',startAmbUnlock);$('#mk').addEventListener('click',startAmbUnlock);\nfunction onRoom(m){room=m;const me=m.players.find(p=>p.id===pid);\n if(m.phase==='lobby'){view('lobby');$('#lc').textContent=m.code;$('#lk').value=location.origin+'/?salle='+m.code;\n  $('#lpl').innerHTML=m.players.map(p=>'<li><span>'+(p.id===m.host?'👑 ':'')+esc(p.name)+'</span><span>'+(p.id===pid?'vous':'')+'</span></li>').join('');\n  $('#go').hidden=m.host!==pid;$('#lw').textContent=m.host===pid?'Vous êtes l’hôte : lancez la partie quand tout le monde est là.':'En attente du lancement par l’hôte…'}\n else{$('#board').innerHTML=m.players.map(p=>'<span class=\"pl'+(p.alive?'':' out')+(p.id===pid?' me':'')+(m.phase==='q'&&p.a?' dn':'')+'\">'+esc(p.name)+' · '+fmt(p.gain)+(m.phase==='q'&&p.a?' ✔':'')+'</span>').join('');\n  $('#fifty').classList.toggle('used',!!(me&&me.f));$('#fifty').disabled=!(me&&me.alive&&!me.f&&m.step>=4&&m.phase==='q'&&!locked&&!me.a);\n  $('#walk').disabled=!(me&&me.alive&&m.step>0&&m.phase==='q'&&!locked&&!me.a)}\n if(m.phase==='end'){$('#again').hidden=m.host!==pid;$('#ewait').textContent=m.host===pid?'':'L’hôte peut relancer une partie.'}}\n/* ---- partie ---- */\nconst ans=$('#answers');\n['A','B','C','D'].forEach((l,i)=>{const b=document.createElement('button');b.className='ans hex';b.style.setProperty('--i',i);b.innerHTML='<span class=\"in\"><b>'+l+' :</b><span></span></span>';b.onclick=()=>choose(i);ans.append(b)});\nconst A=[...ans.children],lad=$('#ladder');\nAM.forEach((a,i)=>{const li=document.createElement('li');li.innerHTML='<span>'+(i+1)+'</span><span>'+fmt(a)+'</span>';if(SAFE.includes(i))li.className='safe';lad.append(li)});\nfunction newQ(m){cur=m;off=m.now-Date.now();view('game');clearInterval(cdn);iAlive=m.alive;qOpen=true;locked=m.sel!==null;lastT=-1;\n $('#info').textContent='Question '+(m.step+1)+' sur 15 · '+LV[STEP[m.step]]+' · pour '+fmt(AM[m.step]);$('#qtxt').textContent=m.q;\n A.forEach((b,i)=>{b.className='ans hex';b.disabled=true;b.lastChild.lastChild.textContent=m.a[i];void b.offsetWidth;setTimeout(()=>{b.classList.add('show');b.disabled=!m.alive||locked;if(m.hid.includes(i))b.classList.add('gone');if(m.sel===i)b.classList.add('sel','pend')},50)});\n [...lad.children].forEach((li,i)=>{li.classList.toggle('cur',i===m.step);li.classList.toggle('done',i<m.step)});\n $('#panel').innerHTML=!m.alive?'<p>Vous êtes éliminé : vous suivez la partie en direct.</p>':locked?'<p>Réponse envoyée…</p>':'';\n sfx.q();clearInterval(tmr);tmr=setInterval(tick,250);tick();stopAmb();if(m.alive)setTimeout(()=>{if(qOpen&&cur===m)startAmb()},1500);if(room)onRoom(room)}\nfunction tick(){const t=Math.max(0,Math.min(30,Math.ceil((cur.endAt-(Date.now()+off))/1000)));if(t===lastT)return;lastT=t;\n $('#timer b').textContent=t;$('#timer i').style.transform='scaleX('+t/30+')';$('#timer').classList.toggle('low',t<=10);\n if(t===10&&drone&&!locked)setBeat(450);if(t<=5&&t>0&&qOpen&&iAlive&&!locked)tone(1000,.08)}\nfunction choose(i){if(locked||!iAlive||!qOpen)return;locked=true;send({t:'answer',i});A[i].classList.add('sel','pend');A.forEach(b=>b.disabled=true);$('#panel').innerHTML='<p>Réponse envoyée… en attente des autres joueurs.</p>';setBeat(350);sfx.sel();if(room)onRoom(room)}\n$('#fifty').onclick=()=>send({t:'fifty'});\n$('#walk').onclick=()=>{if(confirm('Quitter la partie et empocher '+fmt(AM[cur.step-1])+' ?'))send({t:'walk'})};\nfunction onHid(m){m.idx.forEach(i=>A[i].classList.add('gone'));sfx.ok()}\nfunction onReveal(m){qOpen=false;clearInterval(tmr);stopAmb();A.forEach(b=>{b.disabled=true;b.classList.remove('sel','pend')});\n const me=m.results.find(r=>r.id===pid);\n if(me&&!me.ok&&me.pick!==null)A[me.pick].classList.add('ko');A[m.correct].classList.add('ok');\n if(me&&!me.ok)sfx.ko();else if(me)sfx.ok();else sfx.ding();\n if(me&&me.ok)lad.children[m.step].classList.add('done');\n $('#panel').innerHTML='<p>'+(me?(me.ok?'Bonne réponse ! Vous avez '+fmt(me.gain)+'.':'Raté ! Vous repartez avec '+fmt(me.gain)+'.'):'')+'</p><div id=\"board2\">'+m.results.map(r=>'<span class=\"pl '+(r.ok?'dn':'out')+'\">'+esc(r.name)+(r.ok?' ✔':' ✘')+'</span>').join('')+'</div><p id=\"nxt\"></p>';\n const o2=m.now-Date.now();clearInterval(cdn);cdn=setInterval(()=>{const s=Math.max(0,Math.ceil((m.nextAt-(Date.now()+o2))/1000));const e=$('#nxt');if(e)e.textContent='Suite dans '+s+' s'},300)}\nfunction onEnd(m){clearInterval(tmr);clearInterval(cdn);stopAmb();qOpen=false;view('end');const r=m.ranking,mine=r.find(x=>x.id===pid);\n $('#gain').textContent=mine?fmt(mine.gain):'';$('#etitle').textContent=r[0]?(r[0].id===pid?'Vous gagnez !':'Vainqueur : '+r[0].name):'Fin de partie';\n $('#rk').innerHTML=r.map((x,i)=>'<li><span>'+['🥇','🥈','🥉'][i]+(i<3?' ':(i+1)+'. ')+esc(x.name)+'</span><span>'+fmt(x.gain)+'</span></li>').join('');\n if(room)onRoom(room);if(mine&&r[0].id===pid&&mine.gain>0){sfx.win();confetti()}else sfx.ding()}\nfunction confetti(){for(let i=0;i<70;i++){const c=document.createElement('i');c.className='conf';c.style.left=Math.random()*100+'vw';c.style.background=['#e9c46a','#f08a00','#fff','#4f8cff'][i%4];c.style.animationDuration=2+Math.random()*2.5+'s';c.style.animationDelay=Math.random()+'s';document.body.append(c);setTimeout(()=>c.remove(),6000)}}\n$('#again').onclick=()=>send({t:'again'});\n$('#home').onclick=()=>{code=null;ss.set('code','');if(ws)ws.close();location.href=location.pathname};\n/* ---- base de questions partagée ---- */\nconst LVL=LV.map(x=>x.toLowerCase()),msg=t=>$('#dbmsg').textContent=t;\n$('#fl').innerHTML=LV.map((l,i)=>'<option value=\"'+i+'\">Difficulté : '+l+'</option>').join('');\nasync function stats(){try{const s=await(await fetch('/api/stats')).json();$('#dbst').textContent=s.total+' questions · '+LV.map((l,i)=>l+' : '+s.levels[i]).join(' · ')+' · dont '+s.extra+' ajoutée(s).'}catch(e){$('#dbst').textContent='Statistiques indisponibles.'}}\nasync function push(rows){try{const r=await fetch('/api/questions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:$('#ak').value,rows})});const j=await r.json();if(!r.ok){msg(j.error||'Erreur.');return null}stats();return j}catch(e){msg('Serveur injoignable.');return null}}\n$('#dbbtn').onclick=()=>{$('#db').hidden=false;msg('');stats()};$('#dbback').onclick=()=>$('#db').hidden=true;\n$('#fadd').onclick=async()=>{const v=['fq','fa','fb','fc','fd'].map(i=>$('#'+i).value.trim());if(v.some(x=>!x)){msg('Remplissez la question et les quatre réponses.');return}\n const j=await push([[...v,+$('#fr').value,+$('#fl').value]]);if(j){msg(j.added?'Question ajoutée pour tous les joueurs.':'Cette question existe déjà.');if(j.added)['fq','fa','fb','fc','fd'].forEach(i=>$('#'+i).value='')}};\n$('#xf').onchange=e=>{const f=e.target.files[0];if(!f)return;if(!window.XLSX){msg('Le lecteur Excel n’a pas pu se charger. Vérifiez votre connexion.');return}\n const r=new FileReader();r.onload=async ev=>{try{const wb=XLSX.read(ev.target.result,{type:'array',cellStyles:true}),ws2=wb.Sheets[wb.SheetNames[0]],rows=XLSX.utils.sheet_to_json(ws2,{header:1,defval:''});const out=[];let bad=0;\n rows.forEach((r,ri)=>{const q=String(r[0]).trim();if(!q||q==='Question')return;const l=LVL.indexOf(String(r[5]).trim().toLowerCase()),k=String(r[7]||'').trim().toUpperCase().replace('RÉPONSE','').trim();let c=-1;\n  if(/^[ABCD]$/.test(k))c='ABCD'.indexOf(k);else{const m=[1,2,3,4].filter(j=>{const s=(ws2[XLSX.utils.encode_cell({r:ri,c:j})]||{}).s;return s&&s.patternType&&s.patternType!=='none'});if(m.length===1)c=m[0]-1}\n  const a=[1,2,3,4].map(j=>String(r[j]).trim());if(l<0||c<0||a.some(x=>!x)){bad++;return}out.push([q,...a,c,l])});\n const j=await push(out);if(j)msg(j.added+' ajoutée(s), '+j.dup+' doublon(s), '+(j.bad+bad)+' ligne(s) ignorée(s)'+(bad?' (bonne réponse ou difficulté introuvable : ajoutez la colonne « Bonne réponse »).':'.'))}catch(x){msg('Fichier illisible. Utilisez un .xlsx au même modèle.')}};r.readAsArrayBuffer(f);e.target.value=''};\n</script></body></html>\n";
const XF = path.join(DIR, 'extra.json');
let EXTRA = [];
try { EXTRA = JSON.parse(fs.readFileSync(XF, 'utf8')); Q.push(...EXTRA); } catch (e) {}
const persist = () => { try { fs.mkdirSync(DIR, { recursive: true }); fs.writeFileSync(XF, JSON.stringify(EXTRA)); } catch (e) { console.error('Sauvegarde impossible :', e.message); } };
const validRow = r => Array.isArray(r) && r.length === 7 && r.slice(0, 5).every(x => typeof x === 'string' && x.trim() && x.length < 300) &&
  Number.isInteger(r[5]) && r[5] >= 0 && r[5] < 4 && Number.isInteger(r[6]) && r[6] >= 0 && r[6] < 6;
const stats = () => ({ total: Q.length, extra: EXTRA.length, levels: [0, 1, 2, 3, 4, 5].map(l => Q.filter(q => q[6] === l).length) });

// ---- HTTP (site statique + API)
const json = (res, c, o) => { res.writeHead(c, { 'Content-Type': 'application/json' }); res.end(JSON.stringify(o)); };
const server = http.createServer((req, res) => {
  let u; try { u = new URL(req.url, 'http://x'); } catch (e) { res.writeHead(400); return res.end(); }
  if (u.pathname === '/health') return res.end('ok');
  if (u.pathname === '/api/stats') return json(res, 200, stats());
  if (u.pathname === '/api/questions' && req.method === 'POST') {
    let b = ''; req.on('data', d => { b += d; if (b.length > 2e6) req.destroy(); });
    return req.on('end', () => {
      try {
        const { key, rows } = JSON.parse(b);
        if (process.env.ADMIN_KEY && key !== process.env.ADMIN_KEY) return json(res, 403, { error: 'Code admin incorrect.' });
        let added = 0, dup = 0, bad = 0;
        (Array.isArray(rows) ? rows : []).forEach(r => {
          if (!validRow(r)) return bad++;
          r = r.map((x, i) => (i < 5 ? x.trim() : x));
          if (Q.some(q => q[0].toLowerCase() === r[0].toLowerCase())) return dup++;
          Q.push(r); EXTRA.push(r); added++;
        });
        if (added) persist();
        json(res, 200, { added, dup, bad, ...stats() });
      } catch (e) { json(res, 400, { error: 'Requête invalide.' }); }
    });
  }
  if (u.pathname === '/' || u.pathname === '/index.html') { res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' }); return res.end(HTML); }
  res.writeHead(302, { Location: '/' }); res.end();
});

// ---- Salles
const rooms = new Map();
const rnd = n => Math.floor(Math.random() * n);
const send = (ws, o) => { if (ws && ws.readyState === 1) ws.send(JSON.stringify(o)); };
const bc = (r, o) => r.players.forEach(p => send(p.ws, o));
const newCode = () => { const L = 'ABCDEFGHJKLMNPQRSTUVWXYZ'; let c; do { c = Array.from({ length: 4 }, () => L[rnd(L.length)]).join(''); } while (rooms.has(c)); return c; };
const pub = r => ({ t: 'room', code: r.code, host: r.host, phase: r.phase, step: r.step,
  players: [...r.players.values()].map(p => ({ id: p.id, name: p.name, alive: p.alive, gain: p.gain, a: p.answer !== null, on: !!p.ws, f: p.f })) });
const rank = r => [...r.players.values()].map(p => ({ id: p.id, name: p.name, gain: p.gain, time: Math.round(p.time), alive: p.alive }))
  .sort((a, b) => b.gain - a.gain || a.time - b.time);

function join(ws, m, create) {
  const name = String(m.name || '').trim().slice(0, 16);
  if (!name) return send(ws, { t: 'err', m: 'Entrez votre prénom.' });
  let r, p;
  if (create) {
    r = { code: newCode(), players: new Map(), phase: 'lobby', step: -1, used: new Set(), cur: null, host: null, timer: null, last: Date.now() };
    rooms.set(r.code, r);
  } else {
    r = rooms.get(String(m.room || '').toUpperCase());
    if (!r) return send(ws, { t: 'err', m: 'Salle introuvable.', fatal: 1 });
    p = r.players.get(m.pid);
  }
  if (!p) {
    if (r.phase !== 'lobby') return send(ws, { t: 'err', m: 'La partie a déjà commencé.', fatal: 1 });
    if (r.players.size >= 20) return send(ws, { t: 'err', m: 'La salle est pleine (20 joueurs).', fatal: 1 });
    p = { id: crypto.randomUUID(), name, ws: null, alive: true, gain: 0, time: 0, answer: null, at: 0, f: false, hid: [] };
    r.players.set(p.id, p);
  }
  p.ws = ws; ws.pid = p.id; ws.room = r.code; r.last = Date.now();
  if (!r.host || !r.players.get(r.host)) r.host = p.id;
  send(ws, { t: 'joined', pid: p.id, code: r.code });
  bc(r, pub(r));
  if (r.phase === 'q') sendQ(r, p);
  if (r.phase === 'end') send(ws, { t: 'end', ranking: rank(r) });
}
const sendQ = (r, p) => send(p.ws, { t: 'q', step: r.step, q: r.cur[0], a: r.cur.slice(1, 5), endAt: r.endAt, now: Date.now(), alive: p.alive, hid: p.hid, sel: p.answer });

function begin(r) {
  r.step = -1; r.used = new Set();
  r.players.forEach(p => { p.alive = true; p.gain = 0; p.time = 0; p.f = false; p.answer = null; p.hid = []; });
  nextQ(r);
}
function nextQ(r) {
  r.step++; r.phase = 'q';
  const lv = STEP[r.step], all = Q.map((q, i) => i);
  let pool = all.filter(i => Q[i][6] === lv && !r.used.has(i));
  if (!pool.length) pool = all.filter(i => Q[i][6] === lv);
  if (!pool.length) pool = all;
  const i = pool[rnd(pool.length)]; r.used.add(i); r.cur = Q[i];
  r.startAt = Date.now() + GRACE; r.endAt = r.startAt + QT;
  r.players.forEach(p => { p.answer = null; p.hid = []; });
  r.players.forEach(p => sendQ(r, p));
  bc(r, pub(r));
  clearTimeout(r.timer); r.timer = setTimeout(() => reveal(r), QT + GRACE + 300);
}
function checkAll(r) {
  if (r.phase !== 'q') return;
  const pl = [...r.players.values()].filter(p => p.alive && p.ws);
  if (pl.every(p => p.answer !== null)) { clearTimeout(r.timer); r.timer = setTimeout(() => reveal(r), 700); }
}
function reveal(r) {
  if (r.phase !== 'q') return;
  r.phase = 'reveal'; clearTimeout(r.timer);
  const c = r.cur[5], res = [];
  r.players.forEach(p => {
    if (!p.alive) return;
    const ok = p.answer === c;
    if (ok) { p.gain = AM[r.step]; p.time += Math.min(QT, Math.max(0, p.at - r.startAt)) / 1000; }
    else { p.alive = false; p.gain = safe(r.step); p.time += QT / 1000; }
    res.push({ id: p.id, name: p.name, pick: p.answer, ok, gain: p.gain });
  });
  bc(r, { t: 'reveal', step: r.step, correct: c, results: res, nextAt: Date.now() + PAUSE, now: Date.now() });
  bc(r, pub(r));
  r.timer = setTimeout(() => {
    const alive = [...r.players.values()].some(p => p.alive);
    if (r.step >= 14 || !alive) { r.phase = 'end'; bc(r, { t: 'end', ranking: rank(r) }); bc(r, pub(r)); } else nextQ(r);
  }, PAUSE);
}

function onMsg(ws, m) {
  if (m.t === 'create') return join(ws, m, true);
  if (m.t === 'join') return join(ws, m, false);
  const r = rooms.get(ws.room), p = r && r.players.get(ws.pid);
  if (!p) return;
  r.last = Date.now();
  if (m.t === 'start' && r.host === p.id && r.phase === 'lobby') begin(r);
  else if (m.t === 'again' && r.host === p.id && r.phase === 'end') {
    r.players.forEach((x, id) => { if (!x.ws) r.players.delete(id); });
    r.phase = 'lobby'; r.step = -1; r.players.forEach(x => { x.alive = true; x.gain = 0; });
    bc(r, pub(r));
  } else if (m.t === 'answer' && r.phase === 'q' && p.alive && p.answer === null && Number.isInteger(m.i) && m.i >= 0 && m.i < 4 && !p.hid.includes(m.i) && Date.now() <= r.endAt + 500) {
    p.answer = m.i; p.at = Date.now(); bc(r, pub(r)); checkAll(r);
  } else if (m.t === 'fifty' && r.phase === 'q' && p.alive && !p.f && r.step >= 4 && p.answer === null) {
    p.f = true;
    p.hid = [0, 1, 2, 3].filter(i => i !== r.cur[5]).sort(() => Math.random() - .5).slice(0, 2);
    send(p.ws, { t: 'hid', idx: p.hid }); bc(r, pub(r));
  } else if (m.t === 'walk' && r.phase === 'q' && p.alive && r.step > 0 && p.answer === null) {
    p.gain = AM[r.step - 1]; p.alive = false; bc(r, pub(r)); checkAll(r);
  }
}

const wss = new WebSocketServer({ server, maxPayload: 4096 });
wss.on('connection', ws => {
  ws.isAlive = true; ws.on('pong', () => { ws.isAlive = true; });
  ws.on('message', d => { let m; try { m = JSON.parse(d); } catch (e) { return; } if (m && typeof m === 'object') onMsg(ws, m); });
  ws.on('close', () => {
    const r = rooms.get(ws.room), p = r && r.players.get(ws.pid);
    if (!p || p.ws !== ws) return;
    p.ws = null; r.last = Date.now();
    if (r.phase === 'lobby') r.players.delete(p.id);
    if (r.host === p.id) { const n = [...r.players.values()].find(x => x.ws); if (n) r.host = n.id; }
    if (!r.players.size) { clearTimeout(r.timer); rooms.delete(r.code); return; }
    bc(r, pub(r)); checkAll(r);
  });
});
setInterval(() => wss.clients.forEach(ws => { if (!ws.isAlive) return ws.terminate(); ws.isAlive = false; ws.ping(); }), 25000);
setInterval(() => rooms.forEach((r, c) => {
  if (Date.now() - r.last > 600000 && ![...r.players.values()].some(p => p.ws)) { clearTimeout(r.timer); rooms.delete(c); }
}), 60000);
server.listen(PORT, () => console.log('Quiz en ligne sur le port ' + PORT + ' (' + Q.length + ' questions)'));
